import { useState } from "react";
import { FlippableItem } from "./flippable-item";
import { Meta } from "@storybook/react";
import styles from "./flippable-item-stories.module.less";
import Button from "@/core/components/primitives/parks-button/parks-button";
import { desktopOnlyMode } from "../../../../.storybook/preview";

const meta = {
  title: "Primitives/FlippableItem",
  component: FlippableItem,
  parameters: {
    chromatic: desktopOnlyMode,
  },
} satisfies Meta<typeof FlippableItem>;

export default meta;

export const Default = {
  render: function StoryComponent() {
    const [isFlipped, setIsFlipped] = useState(false);
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: "2rem", alignItems: "center" }}>
        <FlippableItem isFlipped={isFlipped} className={styles.card}>
          <div style={{ backgroundColor: "lightblue", height: "100%", textAlign: "center" }}>Front</div>
          <div style={{ backgroundColor: "lightgreen", height: "100%", textAlign: "center" }}>Back</div>
        </FlippableItem>
        <Button onClick={() => setIsFlipped((prev) => !prev)} label="Flip it!" />
      </div>
    );
  },
};
